//! Consolidated SQL DDL generation with inferred types and FK constraints.

use crate::engine::erd::sanitize_ident;
use crate::types::{CrossTableRelationship, TableDataDto};

pub fn generate_sql(tables: &[TableDataDto], relationships: &[CrossTableRelationship]) -> String {
    let mut out = String::from(
        "-- NormaFlow consolidated schema DDL\n-- Generated by the NormaFlow Rust engine\n\n",
    );
    out.push_str("PRAGMA foreign_keys = ON;\n\n");

    for table in tables {
        let t_name = sanitize_ident(&table.table_name);
        out.push_str(&format!("CREATE TABLE {t_name} (\n"));

        let mut cols: Vec<String> = Vec::with_capacity(table.headers.len());
        let is_composite = table.primary_key.len() > 1;
        for (idx, header) in table.headers.iter().enumerate() {
            let col = sanitize_ident(header);
            let col_type = table
                .column_types
                .get(idx)
                .map(String::as_str)
                .unwrap_or("TEXT");
            let is_pk = table.primary_key.iter().any(|pk| sanitize_ident(pk) == col);
            let pk_clause = if is_pk && !is_composite {
                " PRIMARY KEY"
            } else if is_pk {
                " NOT NULL"
            } else {
                ""
            };
            cols.push(format!("  {col} {col_type}{pk_clause}"));
        }

        if is_composite {
            let pk_cols: Vec<String> = table
                .primary_key
                .iter()
                .map(|pk| sanitize_ident(pk))
                .collect();
            cols.push(format!("  PRIMARY KEY ({})", pk_cols.join(", ")));
        }

        for rel in relationships
            .iter()
            .filter(|r| r.source_table == table.table_name)
        {
            cols.push(format!(
                "  CONSTRAINT fk_{}_{} FOREIGN KEY ({}) REFERENCES {}({})",
                t_name,
                sanitize_ident(&rel.source_column),
                sanitize_ident(&rel.source_column),
                sanitize_ident(&rel.target_table),
                sanitize_ident(&rel.target_column)
            ));
        }

        // Index suggestions for FK columns (portable subset).
        out.push_str(&cols.join(",\n"));
        out.push_str("\n);\n\n");

        for rel in relationships
            .iter()
            .filter(|r| r.source_table == table.table_name)
        {
            out.push_str(&format!(
                "CREATE INDEX idx_{}_{} ON {}({});\n\n",
                t_name,
                sanitize_ident(&rel.source_column),
                t_name,
                sanitize_ident(&rel.source_column)
            ));
        }
    }

    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::EntityTag;

    #[test]
    fn ddl_types_and_constraints() {
        let tables = vec![
            TableDataDto {
                table_name: "items".into(),
                file_name: "items.csv".into(),
                headers: vec!["item_id".into(), "cost".into()],
                row_count: 2,
                skipped_rows: 0,
                primary_key: vec!["item_id".into()],
                ner_tags: Vec::<EntityTag>::new(),
                column_types: vec!["INTEGER".into(), "REAL".into()],
                value_samples: vec![],
            },
            TableDataDto {
                table_name: "orders".into(),
                file_name: "orders.csv".into(),
                headers: vec!["order_id".into(), "item_id".into()],
                row_count: 2,
                skipped_rows: 0,
                primary_key: vec!["order_id".into()],
                ner_tags: Vec::<EntityTag>::new(),
                column_types: vec!["INTEGER".into(), "INTEGER".into()],
                value_samples: vec![],
            },
        ];
        let rels = vec![CrossTableRelationship {
            source_table: "orders".into(),
            source_column: "item_id".into(),
            target_table: "items".into(),
            target_column: "item_id".into(),
            cardinality: "1:N".into(),
            confidence: 0.9,
            match_ratio: 0.9,
            detected_by: "VALUE_OVERLAP".into(),
        }];
        let sql = generate_sql(&tables, &rels);
        assert!(sql.contains("item_id INTEGER PRIMARY KEY"));
        assert!(sql.contains("cost REAL"));
        assert!(!sql.contains("VARCHAR(255)")); // regression: everything was VARCHAR before
        assert!(sql.contains("FOREIGN KEY (item_id) REFERENCES items(item_id)"));
        assert!(sql.contains("CREATE INDEX idx_orders_item_id"));
    }

    #[test]
    fn composite_primary_key_table_constraint() {
        let tables = vec![TableDataDto {
            table_name: "order_items".into(),
            file_name: "order_items.csv".into(),
            headers: vec![
                "order_id".into(),
                "product_id".into(),
                "quantity".into(),
            ],
            row_count: 1,
            skipped_rows: 0,
            primary_key: vec!["order_id".into(), "product_id".into()],
            ner_tags: Vec::<EntityTag>::new(),
            column_types: vec!["INTEGER".into(), "INTEGER".into(), "INTEGER".into()],
            value_samples: vec![],
        }];
        let sql = generate_sql(&tables, &[]);
        assert!(sql.contains("order_id INTEGER NOT NULL"));
        assert!(sql.contains("product_id INTEGER NOT NULL"));
        assert!(sql.contains("PRIMARY KEY (order_id, product_id)"));
        assert!(!sql.contains("order_id INTEGER PRIMARY KEY"));
        assert!(!sql.contains("product_id INTEGER PRIMARY KEY"));
    }
}
